<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import {httpClient} from '@/shared/http/client'
const props=defineProps<{caseId:string;businessId:string}>()
interface Source {file_id:string;provider:string;state:string;revision:number;review:{fields?:Record<string,string>;adopted?:unknown};program?:{fields?:Record<string,string>;items?:{description:string;quantity:string;unitPrice:string}[]}}
const source=ref<Source|null>(),image=ref(''),type=ref(''),error=ref(''),loading=ref(false)
const fieldNames:Record<string,string>={claimNo:'报案号',insuranceCompany:'保险公司',vehicleVin:'车架号',vehiclePlate:'车牌号',amountCandidate:'核损总额'}
let generation=0
async function load(){const request=++generation;loading.value=true;error.value='';source.value=undefined;if(image.value)URL.revokeObjectURL(image.value);image.value='';try{const result=(await httpClient.get<{data:Source|null}>(`/quotations/cases/${props.caseId}/sources/${props.businessId}`)).data.data;if(request!==generation)return;source.value=result;if(result){const file=await httpClient.get<Blob>(`/materials/${result.file_id}/download`,{responseType:'blob'});if(request!==generation)return;type.value=file.data.type;image.value=URL.createObjectURL(file.data)}}catch(e){if(request===generation)error.value=e instanceof Error?e.message:'同步资料暂不可用'}finally{if(request===generation)loading.value=false}}
watch(()=>[props.caseId,props.businessId],()=>void load(),{immediate:true});onUnmounted(()=>{generation++;if(image.value)URL.revokeObjectURL(image.value)})
</script>
<template><section class="source"><p v-if="loading" aria-busy="true">正在同步原件与识别信息…</p><p v-if="error" role="alert">{{ error }} <button @click="load">重试</button></p><p v-else-if="source===null">历史版本未记录识别关联。</p><details v-if="source"><summary>原件与核对信息 · {{ source.provider==='MOCK_V1'?'模拟候选':source.state==='FAILED'?'识别失败后人工补录':'识别候选' }}</summary><img v-if="image&&type.startsWith('image/')" :src="image" alt="该提交版本的原件"/><iframe v-else-if="image" :src="image" title="该提交版本的原件"/><dl v-for="(name,key) in fieldNames" :key="key"><dt>{{ name }}</dt><dd>候选：{{ source.program?.fields?.[key]||'未识别' }}</dd><dd>核对：{{ source.review.fields?.[key]||'未采用 / 原件未载明' }}</dd></dl><div v-if="source.program?.items?.length"><h4>识别明细候选</h4><p v-for="(item,index) in source.program.items" :key="index">{{ item.description }} · 数量 {{ item.quantity }} · 单价 {{ item.unitPrice }} 元</p></div><p v-if="typeof source.review.adopted==='string'">采用核损金额：{{ source.review.adopted }} 元</p></details></section></template>
<style scoped>.source{margin:16px 0;color:#536a6b;font-size:13px}.source summary{cursor:pointer;padding:12px 0;border-top:1px solid #dce5e4}.source img,.source iframe{width:100%;max-height:360px;object-fit:contain;border:1px solid #dce5e4}.source iframe{height:360px}.source dl{display:grid;grid-template-columns:80px 1fr 1fr;gap:8px;border-bottom:1px solid #dce5e4;padding:10px 0}.source dd{margin:0;overflow-wrap:anywhere}.source dt{color:#20383c}@media(max-width:640px){.source dl{grid-template-columns:1fr}}</style>
